from itertools import permutations

people = ['Harper', 'Jordan', 'Quinn', 'Sawyer']
colors = ['blue', 'green', 'white', 'yellow']
pets = ['bird', 'dog', 'fish', 'rabbit']
drinks = ['cocoa', 'coffee', 'tea', 'water']

def check_constraints(assignment):
    # assignment[i] = {'person': , 'color': , 'pet': , 'drink': }

    # Create position maps for quick lookup
    person_to_pos = {}
    color_to_pos = {}
    pet_to_pos = {}
    drink_to_pos = {}

    for pos in range(4):
        person_to_pos[assignment[pos]['person']] = pos
        color_to_pos[assignment[pos]['color']] = pos
        pet_to_pos[assignment[pos]['pet']] = pos
        drink_to_pos[assignment[pos]['drink']] = pos

    # Check all 10 constraints
    # 1. Quinn is not the person who drinks cocoa
    if assignment[person_to_pos['Quinn']]['drink'] == 'cocoa':
        return False

    # 2. The person in the white house is the rabbit owner
    if assignment[color_to_pos['white']]['pet'] != 'rabbit':
        return False

    # 3. The person in the green house is the person who drinks cocoa
    if assignment[color_to_pos['green']]['drink'] != 'cocoa':
        return False

    # 4. The dog owner lives next to the person who drinks water
    if abs(pet_to_pos['dog'] - drink_to_pos['water']) != 1:
        return False

    # 5. The person who drinks water is Sawyer
    if assignment[drink_to_pos['water']]['person'] != 'Sawyer':
        return False

    # 6. The fish owner lives immediately to the left of Quinn
    if person_to_pos['Quinn'] != pet_to_pos['fish'] + 1:
        return False

    # 7. The person in the blue house lives next to Harper
    if abs(color_to_pos['blue'] - person_to_pos['Harper']) != 1:
        return False

    # 8. The person who drinks coffee is the fish owner
    if drink_to_pos['coffee'] != pet_to_pos['fish']:
        return False

    # 9. Harper is the fish owner
    if assignment[person_to_pos['Harper']]['pet'] != 'fish':
        return False

    # 10. The dog owner lives immediately to the left of the person in the yellow house
    if color_to_pos['yellow'] != pet_to_pos['dog'] + 1:
        return False

    return True

def solve():
    # Brute force search through all permutations
    for person_perm in permutations(people):
        for color_perm in permutations(colors):
            for pet_perm in permutations(pets):
                for drink_perm in permutations(drinks):
                    assignment = {i: {'person': person_perm[i], 'color': color_perm[i], 
                                     'pet': pet_perm[i], 'drink': drink_perm[i]} for i in range(4)}

                    if check_constraints(assignment):
                        # Found valid solution, find who lives in green house
                        for pos in range(4):
                            if assignment[pos]['color'] == 'green':
                                return assignment[pos]['person']
    return None

answer = solve()
print(f"ANSWER: {answer}")
